narrative:
## Building a Well-Organized Application

Let's build a task management system that combines EVERYTHING from L6: interfaces, modules, pub visibility, use statements, and clean organization.

### The Module Structure

```
task_app/
  models module: type definitions
  tasks module: task operations
  display module: output formatting
  main: wiring it together
```

### Models Module

```xiom
module models {
  pub type Task = {
    title: Str;
    done: Bool;
  }

  pub fn new_task(title: Str) -> Task {
    return Task{ title: title, done: false };
  }

  pub fn mark_done(task: &mut Task) {
    task.done = true;
  }
}

module tasks {
  pub interface TaskStore {
    fn add(task: models.Task);
    fn count() -> Int;
  }

  pub type ListStore = {
    items: Vec[models.Task];
  }

  pub fn ListStore.new() -> ListStore {
    return ListStore{ items: Vec[models.Task].new() };
  }

  pub fn ListStore.add(self: &mut ListStore, task: models.Task) {
    self.items.push(task);
  }

  pub fn ListStore.count(self) -> Int {
    return self.items.len();
  }

  pub fn create_default_store() -> ListStore {
    return ListStore.new();
  }
}

module display {
  pub interface Displayable {
    fn display() -> Str;
  }

  pub fn models.Task.display(self) -> Str {
    let status = "[ ]";
    if self.done { status = "[x]"; }
    return status + " " + self.title;
  }

  pub fn show_all[T: Displayable](items: &Vec[T]) {
    let i = 0;
    while i < items.len() {
      let item = match items.get(i) { Some(v) => v, None => continue };
      io.println(item.display());
      i = i + 1;
    }
  }
}

fn main() -> Int {
  var store = tasks.create_default_store();
  store.add(&mut store, models.new_task("Learn interfaces"));
  store.add(&mut store, models.new_task("Master modules"));

  io.println(string.int_to_str(store.count(&store)));
  return 0;
}
```

### What You've Mastered

| Concept | Where Used |
|---------|-----------|
| Interfaces | TaskStore, Displayable |
| Modules | models, tasks, display |
| pub/private | Type definitions, functions |
| use statements | Imports between modules |
| Cross-module interfaces | Interface in one module, implementation in another |
| Generic functions | show_all[T: Displayable] |
| Clean architecture | Models → Tasks → Display, dependencies flow one way |

